fn vec_min_i8(arr: &Vec<i8>) -> i8 {
    // Assumes arr is non-empty.
    let mut m = arr[0];
    for &x in arr.iter().skip(1) {
        if x < m {
            m = x;
        }
    }
    m
}

fn vec_max_i8(arr: &Vec<i8>) -> i8 {
    // Assumes arr is non-empty.
    let mut m = arr[0];
    for &x in arr.iter().skip(1) {
        if x > m {
            m = x;
        }
    }
    m
}

fn percentile(arr: Vec<i8>, q: i8) -> i8 {
    // Assumes: arr is non-empty and 0 <= q <= 100.
    if q <= 0 {
        vec_min_i8(&arr)
    } else if q >= 100 {
        vec_max_i8(&arr)
    } else {
        // For intermediate percentiles, returning any existing element satisfies:
        // - there exists an element <= result (itself)
        // - there exists an element >= result (itself)
        arr[0]
    }
}